// 🔐 Fast2SMS वेबसाइट वेरिफिकेशन कोड
//    Render → Environment → SITE_VERIFY_CODE = (Fast2SMS जो कोड दे, वही)
//    फिर https://wrong-chat-skl8.onrender.com/verify.txt पर वही कोड दिखेगा
const SITE_VERIFY_CODE = String(process.env.SITE_VERIFY_CODE || "").trim();

const DECODED_ASSETS = new Map();
const BOOT_TIME = Date.now();
for (const [routePath, meta] of Object.entries(EMBEDDED_ASSETS)) {
  DECODED_ASSETS.set(routePath, {
    mime: meta.mime,
    buf: Buffer.from(meta.b64, "base64"),
    // 🚀 pre-compressed — 722 KB JS अब ~200 KB में जाता है (तेज़ लोड, कम डेटा)
    gzbuf: meta.gz ? Buffer.from(meta.gz, "base64") : null,
  });
}

const DB_FILE = path.resolve("./wrongchat-runtime-db.json");
const DEFAULT_DB = {
  users: {},
  pairings: {},
  sessions: {},
  userStates: {},
  updatedAt: new Date().toISOString(),
};

function loadDb() {
  try {
    if (fs.existsSync(DB_FILE)) {
      return { ...structuredClone(DEFAULT_DB), ...JSON.parse(fs.readFileSync(DB_FILE, "utf-8")) };
    }
  } catch {}
  return structuredClone(DEFAULT_DB);
}

function saveDb(db) {
  try {
    db.updatedAt = new Date().toISOString();
    fs.writeFileSync(DB_FILE, JSON.stringify(db), "utf-8");
  } catch {}
}

const db = loadDb();
